('App\\Models\\Category', 5, 'bd', 'name', 'Electronics', 1),
('App\\Models\\Product', 2, 'bd', 'name', 'Massage Gun', 2),
('App\\Models\\Product', 2, 'bd', 'description', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Electric Vibration Body muscle massager Fascial Gun & Recovery device</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Specifications:</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Voltage input: 100~240V 50/60Hz</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Output:12.6V</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Type: Li-ion</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Material: PP+ABS</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Massage Head Material: PP</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Capacity: 2500mAh</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Working Hour: 4-5 Hours</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Power cord length:152cm</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Switching mode: double switch, power + gear</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Strength gear: 6 gears adjustable + LED indicator</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">No-load Speed: 3600r/min</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">6 Levels Adjustment: Level 1 – 2100rpm, Level 2 – 2400rpm, Level 3 – 2700rpm, Level 4 -3000rpm, Level 5 – 3300rpm, Level 6 – 3600rpm</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Color: Black/White.</strong></li></ol><p><br></p>', 3),
('App\\Models\\Category', 6, 'bd', 'name', 'Kitchen', 4),
('App\\Models\\Product', 5, 'bd', 'name', 'AC1200 Wireless VoIP GPON Router', 5),
('App\\Models\\Product', 5, 'bd', 'description', '<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"color: rgb(80, 82, 85); background-color: initial;\">Superfast Dual Band WiFi:</strong><span style=\"color: rgb(80, 82, 85); background-color: initial;\"> Up to 1.2 Gbps Wi-Fi speed, 300 Mbps 2.4GHz, 867 Mbps 5GHz</span><a href=\"https://www.tp-link.com/bd/service-provider/gpon/xc220-g3v/#footnote-1\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: currentcolor; background-color: initial;\">*</a></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"color: rgb(80, 82, 85); background-color: initial;\">Full Gigabit Port:</strong><span style=\"color: rgb(80, 82, 85); background-color: initial;\"> Up to 10× faster than standard Ethernet, deliver lightning-fast wired performance</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"color: rgb(80, 82, 85); background-color: initial;\">Supports VOIP Calls:</strong><span style=\"color: rgb(80, 82, 85); background-color: initial;\"> Simply make or receive phone calls over the Internet</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"color: rgb(80, 82, 85); background-color: initial;\">Easy Remote Management:</strong><span style=\"color: rgb(80, 82, 85); background-color: initial;\"> Supports the ONT Management and Control Interface (OMCI), easy to configure and manage remotely from an OLT</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"color: rgb(80, 82, 85); background-color: initial;\">Smooth Connection:</strong><span style=\"color: rgb(80, 82, 85); background-color: initial;\"> Supports VLAN, 802.1q, smooth network connection for IPTV and other services</span></li></ol><p><br></p>', 6),
